function LogoItem({ logo, tabIndex = 0 }: { logo: Logo; tabIndex?: number }) {
    return (
        <a
            className={styles.logo}
            href={logo.href}
            target="_blank"
            rel="noopener noreferrer"
            tabIndex={tabIndex}
            aria-label={logo.label}
            style={{ "--brand-color": logo.brandColor } as CSSProperties}
        >
            <svg
                className={styles.icon}
                viewBox="0 0 24 24"
                aria-hidden="true"
                focusable="false"
            >
                {logo.svgContent}
            </svg>
            <span className={styles.name}>{logo.label}</span>
        </a>
    );
}

export default function PlatformMarquee() {
    return (
        <div className={styles.strip}>
            <p className={styles.eyebrow}>Available on</p>
            <div className={styles.viewport}>
                <div className={styles.track}>
                    {/* First set */}
                    {LOGOS.map((logo) => (
                        <LogoItem key={logo.key} logo={logo} />
                    ))}
                    {/* Duplicate for seamless loop — hidden from a11y */}
                    {LOGOS.map((logo) => (
                        <LogoItem
                            key={`${logo.key}-dup`}
                            logo={logo}
                            tabIndex={-1}
                        />
                    ))}
                </div>
            </div>
        </div>
    );
}
